<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';$user=require_login($pdo);$pageTitle='Meldungen & Beschwerden';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{governance_appeal($pdo,(int)$user['id'],(int)post_string('case_id'),post_string('appeal',16000));redirect('/user/reports.php?id='.(int)post_string('case_id'));}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
$selected=null;if(isset($_GET['id'])){try{$selected=governance_case_for_user($pdo,(int)(is_string($_GET['id'])?$_GET['id']:0),(int)$user['id']);}catch(DomainException){abort_request(404,'Fall nicht gefunden.');}}
$q=$pdo->prepare('SELECT id,case_code,target_type,status,created_at FROM market_reports WHERE reporter_id=? OR subject_user_id=? ORDER BY id DESC LIMIT 100');$q->execute([$user['id'],$user['id']]);$cases=$q->fetchAll();
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><p class="eyebrow">Nachvollziehbar entscheiden</p><h1>Deine Fälle.</h1><p>Hier siehst du deine Meldungen und Entscheidungen, die dich betreffen.</p></div><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?>
<?php if($selected):?><section class="panel"><h2><?=h($selected['case_code'])?></h2><p>Status: <?=h($selected['status'])?> · <?=h($selected['target_type'])?> #<?=(int)$selected['target_id']?></p><h3>Meldegrund</h3><p><?=nl2br(h($selected['reason']))?></p><?php if($selected['decision_reason']):?><h3>Begründete Entscheidung</h3><p><?=nl2br(h($selected['decision_reason']))?></p><?php endif;?><?php if($selected['appeal_resolution']):?><h3>Antwort auf die Beschwerde</h3><p><?=nl2br(h($selected['appeal_resolution']))?></p><?php endif;?>
<?php if($selected['status']==='resolved'&&$selected['appeal_text']===null):?><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="case_id" value="<?=(int)$selected['id']?>"><label class="field">Beschwerde gegen die Entscheidung<textarea name="appeal" minlength="10" maxlength="4000" required></textarea></label><button class="button secondary" type="submit">Beschwerde einreichen</button></form><?php elseif($selected['appeal_text']):?><h3>Deine Beschwerde</h3><p><?=nl2br(h($selected['appeal_text']))?></p><?php endif;?></section><?php endif;?>
<section class="panel"><h2>Fallübersicht</h2><?php if(!$cases):?><p>Noch keine Fälle vorhanden. Melden kannst du einen konkreten Inhalt über seinen Meldezugang.</p><?php endif;?><div class="table-wrap"><table class="data-table"><thead><tr><th>Fall</th><th>Art</th><th>Status</th><th>Datum</th></tr></thead><tbody><?php foreach($cases as $case):?><tr><td><a href="?id=<?=(int)$case['id']?>"><?=h($case['case_code'])?></a></td><td><?=h($case['target_type'])?></td><td><?=h($case['status'])?></td><td><?=h($case['created_at'])?> UTC</td></tr><?php endforeach;?></tbody></table></div></section></main><?php include __DIR__.'/../includes/footer.php';?>
